// ------------------------------------------------------------------------------
// Written here by Tabbit. Generated by Tabbit. DO NOT EDIT.
//
// The runtime, copied in beside the generated code so the output is
// self-contained. Edit it in the Tabbit repository, not here: this file is
// rewritten on every run, and the header above is what lets a later run remove
// it if it ever moves.
// ------------------------------------------------------------------------------

// Tabbit's data updater.
//
// Brings a local copy of the exported data up to date with a copy served over HTTP - a
// CDN, a bucket, a patch server - so a running program can take new data without being
// redeployed. Emitted beside the reader and reads nothing but the manifest, so it knows
// nothing about the schema and never has to change when one does.
//
// The manifest is what the exporter already writes next to the data: one entry per file
// with its size and MD5. Comparing it with the local copy is the whole of the diff, so a
// run downloads what changed and nothing else.
//
// Three properties, because a patcher that fails badly is worse than one that does not
// exist:
//
//   Nothing is replaced until everything has arrived and been checked. Files land in a
//   staging directory first and the local manifest is written last, so an update killed
//   halfway leaves the previous data readable and the next run redoes the difference.
//
//   Every file is checked against the hash the manifest gives for it, so a truncated
//   transfer that a proxy reported as success does not reach the cache.
//
//   A transient failure is retried with a doubling backoff, and a permanent one is not.
//
// Reading is somebody else's job. This produces a directory, and the generated tables
// read it.
//
// ---------------------------------------------------------------------------- libcurl
//
// This is the one file Tabbit emits for C++ that is not self-contained. The standard
// library has no HTTP client, so the transfer is libcurl:
//
//     c++ ... -lcurl
//
// Everything else stays here. The manifest parser and the MD5 are written out below
// rather than pulled from a second library, so turning the updater on costs one link flag
// and nothing more. Turn `WriteUpdater` off and the generated C++ has no dependencies at
// all, which is what it had before.
//
// Header-only and `inline` throughout, like the reader beside it, so including it from
// more than one translation unit is not a link error.

#ifndef TABBIT_UPDATER_H
#define TABBIT_UPDATER_H

#include <curl/curl.h>

#include <algorithm>
#include <cctype>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <functional>
#include <map>
#include <optional>
#include <string>
#include <thread>
#include <vector>

namespace tabbit {

/// What an update is allowed to do. Every member has a working default.
struct UpdateOptions {
  /// The binary exporter writes manifest-binary.json; the JSON exporter writes
  /// manifest-json.json.
  std::string manifest_file_name = "manifest-binary.json";

  /// The first attempt is included, so three is two retries.
  int max_attempts = 3;

  /// Waited before the second attempt. Doubled for each attempt after it.
  std::chrono::milliseconds retry_delay{500};

  std::chrono::seconds request_timeout{30};
  bool verify_hash = true;

  /// Called with one line of progress, when set.
  std::function<void(const std::string&)> log;
};

/// What an update did.
struct UpdateResult {
  bool succeeded = false;
  std::string error;
  bool up_to_date = false;
  int downloaded_count = 0;
  std::int64_t downloaded_bytes = 0;
  int deleted_count = 0;

  /// The directory holding the data. Hand it to the generated accessor's read_all. Set
  /// even on failure, because the previous data is still there and still readable - which
  /// is the point of failing the way this does.
  std::filesystem::path local_path;
};

/// One file of the manifest, and the hash to check it by.
struct ManifestEntry {
  std::string name;
  std::int64_t size = 0;
  std::string hash;
};

namespace detail {

/// What went wrong, and whether trying again could go differently.
struct Failure {
  std::string message;
  bool transient = false;
};

// ------------------------------------------------------------------------------- MD5

/// The MD5 of some bytes, in the lower-case hex the manifest carries.
///
/// Written out rather than linked against OpenSSL, so that turning the updater on costs
/// one link flag and not two. A wrong one could not hide either: every download would
/// fail its hash check on the first run.
inline std::string md5_hex(const std::uint8_t* data, std::size_t length) {
  static const std::uint32_t SHIFTS[64] = {
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5,  9, 14, 20, 5,  9, 14, 20, 5,  9, 14, 20, 5,  9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
  };

  // floor(abs(sin(i + 1)) * 2^32). Tabulated rather than computed: the values never
  // change, and the gate checks them against the published vectors - which is the only
  // reading of sixty-four magic numbers that counts.
  static const std::uint32_t SINES[64] = {
    0xd76aa478u, 0xe8c7b756u, 0x242070dbu, 0xc1bdceeeu,
    0xf57c0fafu, 0x4787c62au, 0xa8304613u, 0xfd469501u,
    0x698098d8u, 0x8b44f7afu, 0xffff5bb1u, 0x895cd7beu,
    0x6b901122u, 0xfd987193u, 0xa679438eu, 0x49b40821u,
    0xf61e2562u, 0xc040b340u, 0x265e5a51u, 0xe9b6c7aau,
    0xd62f105du, 0x02441453u, 0xd8a1e681u, 0xe7d3fbc8u,
    0x21e1cde6u, 0xc33707d6u, 0xf4d50d87u, 0x455a14edu,
    0xa9e3e905u, 0xfcefa3f8u, 0x676f02d9u, 0x8d2a4c8au,
    0xfffa3942u, 0x8771f681u, 0x6d9d6122u, 0xfde5380cu,
    0xa4beea44u, 0x4bdecfa9u, 0xf6bb4b60u, 0xbebfbc70u,
    0x289b7ec6u, 0xeaa127fau, 0xd4ef3085u, 0x04881d05u,
    0xd9d4d039u, 0xe6db99e5u, 0x1fa27cf8u, 0xc4ac5665u,
    0xf4292244u, 0x432aff97u, 0xab9423a7u, 0xfc93a039u,
    0x655b59c3u, 0x8f0ccc92u, 0xffeff47du, 0x85845dd1u,
    0x6fa87e4fu, 0xfe2ce6e0u, 0xa3014314u, 0x4e0811a1u,
    0xf7537e82u, 0xbd3af235u, 0x2ad7d2bbu, 0xeb86d391u,
  };

  std::uint32_t a0 = 0x67452301u, b0 = 0xefcdab89u, c0 = 0x98badcfeu, d0 = 0x10325476u;

  std::vector<std::uint8_t> block(data, data + length);
  const std::uint64_t bit_length = static_cast<std::uint64_t>(length) * 8u;

  block.push_back(0x80);
  while (block.size() % 64 != 56) block.push_back(0);

  for (int i = 0; i < 8; ++i)
    block.push_back(static_cast<std::uint8_t>((bit_length >> (8 * i)) & 0xFFu));

  for (std::size_t offset = 0; offset < block.size(); offset += 64) {
    std::uint32_t words[16];

    for (int i = 0; i < 16; ++i) {
      words[i] = static_cast<std::uint32_t>(block[offset + i * 4])
               | (static_cast<std::uint32_t>(block[offset + i * 4 + 1]) << 8)
               | (static_cast<std::uint32_t>(block[offset + i * 4 + 2]) << 16)
               | (static_cast<std::uint32_t>(block[offset + i * 4 + 3]) << 24);
    }

    std::uint32_t a = a0, b = b0, c = c0, d = d0;

    for (int i = 0; i < 64; ++i) {
      std::uint32_t f;
      int g;

      if (i < 16) {
        f = (b & c) | (~b & d);
        g = i;
      } else if (i < 32) {
        f = (d & b) | (~d & c);
        g = (5 * i + 1) % 16;
      } else if (i < 48) {
        f = b ^ c ^ d;
        g = (3 * i + 5) % 16;
      } else {
        f = c ^ (b | ~d);
        g = (7 * i) % 16;
      }

      f = f + a + SINES[i] + words[g];

      a = d;
      d = c;
      c = b;
      b = b + ((f << SHIFTS[i]) | (f >> (32u - SHIFTS[i])));
    }

    a0 += a;
    b0 += b;
    c0 += c;
    d0 += d;
  }

  static const char HEX[] = "0123456789abcdef";
  std::string hex;
  hex.reserve(32);

  for (std::uint32_t word : { a0, b0, c0, d0 }) {
    for (int byte = 0; byte < 4; ++byte) {
      const std::uint8_t value = static_cast<std::uint8_t>((word >> (8 * byte)) & 0xFFu);

      hex.push_back(HEX[(value >> 4) & 0xF]);
      hex.push_back(HEX[value & 0xF]);
    }
  }

  return hex;
}

// ------------------------------------------------------------------------------ JSON

/// A reader over the manifest's text.
///
/// Not a DOM. This asks a manifest three questions and skips whole values properly
/// rather than searching for substrings - a quoted brace inside a name would defeat the
/// second and does not defeat this.
class JsonReader {
 public:
  explicit JsonReader(const std::string& text) : text_(text) {}

  void skip_whitespace() {
    while (at_ < text_.size()) {
      const char c = text_[at_];

      if (c == ' ' || c == '\t' || c == '\r' || c == '\n')
        ++at_;
      else
        break;
    }
  }

  char peek() const { return at_ < text_.size() ? text_[at_] : '\0'; }
  void step() { ++at_; }

  bool read_string(std::string* out) {
    if (peek() != '"') return false;

    ++at_;

    if (out != nullptr) out->clear();

    while (at_ < text_.size()) {
      char c = text_[at_++];

      if (c == '"') return true;

      if (c == '\\') {
        if (at_ >= text_.size()) return false;

        const char escape = text_[at_++];

        switch (escape) {
          case '"': c = '"'; break;
          case '\\': c = '\\'; break;
          case '/': c = '/'; break;
          case 'b': c = '\b'; break;
          case 'f': c = '\f'; break;
          case 'n': c = '\n'; break;
          case 'r': c = '\r'; break;
          case 't': c = '\t'; break;
          case 'u':
            // A manifest names files and hex digests, so anything outside ASCII here is a
            // document this was not written for. The escape is stepped over and a
            // replacement kept, which keeps the parse honest.
            if (at_ + 4 > text_.size()) return false;

            at_ += 4;
            c = '?';
            break;
          default:
            return false;
        }
      }

      if (out != nullptr) out->push_back(c);
    }

    return false;
  }

  bool skip_value() {
    const char c = peek();

    if (c == '{') return skip_container('}');
    if (c == '[') return skip_container(']');
    if (c == '"') return read_string(nullptr);
    if (c == '\0') return false;

    // A number or one of the three literals: both run until something that cannot be
    // part of one.
    const std::size_t start = at_;

    while (at_ < text_.size()) {
      const char at = text_[at_];

      if (at == ',' || at == '}' || at == ']' || at == ' ' || at == '\t'
          || at == '\r' || at == '\n')
        break;

      ++at_;
    }

    return at_ != start;
  }

  /// The text a skip_value just stepped over, for the one place a number is wanted.
  std::string text_between(std::size_t start) const {
    return text_.substr(start, at_ - start);
  }

  std::size_t position() const { return at_; }

 private:
  bool skip_container(char close) {
    ++at_;
    skip_whitespace();

    if (peek() == close) {
      ++at_;
      return true;
    }

    for (;;) {
      skip_whitespace();

      if (close == '}') {
        if (!read_string(nullptr)) return false;

        skip_whitespace();

        if (peek() != ':') return false;

        ++at_;
        skip_whitespace();
      }

      if (!skip_value()) return false;

      skip_whitespace();

      if (peek() == close) {
        ++at_;
        return true;
      }

      if (peek() != ',') return false;

      ++at_;
    }
  }

  const std::string& text_;
  std::size_t at_ = 0;
};

}  // namespace detail

/// Reads the entries out of a manifest's JSON. Empty when it is not one.
inline std::vector<ManifestEntry> parse_manifest(const std::string& text) {
  detail::JsonReader json(text);
  std::vector<ManifestEntry> entries;

  json.skip_whitespace();

  if (json.peek() != '{') return {};

  json.step();

  // Walk the top-level object until "Items", stepping properly over whatever else the
  // manifest carries.
  for (;;) {
    std::string key;

    json.skip_whitespace();

    if (!json.read_string(&key)) return {};

    json.skip_whitespace();

    if (json.peek() != ':') return {};

    json.step();
    json.skip_whitespace();

    if (key == "Items") break;

    if (!json.skip_value()) return {};

    json.skip_whitespace();

    if (json.peek() != ',') return {};

    json.step();
  }

  if (json.peek() != '[') return {};

  json.step();
  json.skip_whitespace();

  if (json.peek() == ']') return entries;

  for (;;) {
    ManifestEntry entry;

    json.skip_whitespace();

    if (json.peek() != '{') return {};

    json.step();
    json.skip_whitespace();

    while (json.peek() != '}') {
      std::string key;

      json.skip_whitespace();

      if (!json.read_string(&key)) return {};

      json.skip_whitespace();

      if (json.peek() != ':') return {};

      json.step();
      json.skip_whitespace();

      if (key == "Name") {
        if (!json.read_string(&entry.name)) return {};
      } else if (key == "Hash") {
        if (!json.read_string(&entry.hash)) return {};
      } else if (key == "Size") {
        const std::size_t start = json.position();

        if (!json.skip_value()) return {};

        entry.size = std::strtoll(json.text_between(start).c_str(), nullptr, 10);
      } else if (!json.skip_value()) {
        return {};
      }

      json.skip_whitespace();

      if (json.peek() == ',') {
        json.step();
        json.skip_whitespace();
      }
    }

    json.step();

    if (!entry.name.empty()) entries.push_back(entry);

    json.skip_whitespace();

    if (json.peek() == ']') return entries;

    if (json.peek() != ',') return {};

    json.step();
  }
}

namespace detail {

// -------------------------------------------------------------------------- transfer

inline std::size_t write_body(char* chunk, std::size_t size, std::size_t count,
                              void* context) {
  auto* body = static_cast<std::vector<std::uint8_t>*>(context);
  const std::size_t arriving = size * count;

  body->insert(body->end(), chunk, chunk + arriving);
  return arriving;
}

/// Joins a base URL and a file name.
///
/// Not a path join, which on Windows produces a backslash and a URL no server will
/// answer.
inline std::string join_url(std::string base_url, const std::string& name) {
  while (!base_url.empty() && base_url.back() == '/') base_url.pop_back();

  std::string tail = name;
  std::replace(tail.begin(), tail.end(), '\\', '/');

  return base_url + "/" + tail;
}

/// One request.
inline std::optional<Failure> fetch(const std::string& url, const UpdateOptions& options,
                                    std::vector<std::uint8_t>* body) {
  CURL* handle = curl_easy_init();

  if (handle == nullptr)
    return Failure{ "'" + url + "' could not be prepared for transfer.", false };

  body->clear();

  curl_easy_setopt(handle, CURLOPT_URL, url.c_str());
  curl_easy_setopt(handle, CURLOPT_FOLLOWLOCATION, 1L);
  curl_easy_setopt(handle, CURLOPT_WRITEFUNCTION, write_body);
  curl_easy_setopt(handle, CURLOPT_WRITEDATA, static_cast<void*>(body));
  curl_easy_setopt(handle, CURLOPT_CONNECTTIMEOUT,
                   static_cast<long>(options.request_timeout.count()));
  curl_easy_setopt(handle, CURLOPT_TIMEOUT,
                   static_cast<long>(options.request_timeout.count()));

  const CURLcode code = curl_easy_perform(handle);

  if (code != CURLE_OK) {
    const std::string why = curl_easy_strerror(code);

    curl_easy_cleanup(handle);

    // The request never got an answer - DNS, a refused connection, a timeout.
    return Failure{ "'" + url + "' could not be reached: " + why + ".", true };
  }

  long status = 0;
  curl_easy_getinfo(handle, CURLINFO_RESPONSE_CODE, &status);
  curl_easy_cleanup(handle);

  if (status >= 200 && status < 300) return std::nullopt;

  const std::string message = "'" + url + "' answered " + std::to_string(status) + ".";

  // 408 and 429 are the server asking for another attempt, and 5xx is it failing on its
  // own account. A 404 is an answer: retrying it costs three round trips to hear the
  // same thing.
  const bool transient =
      status == 408 || status == 429 || (status >= 500 && status <= 599);

  return Failure{ message, transient };
}

/// Fetches one URL, retrying what is worth retrying.
inline std::optional<Failure> download(const std::string& url, const UpdateOptions& options,
                                       std::vector<std::uint8_t>* body) {
  auto delay = options.retry_delay;
  // Not std::max. On Windows curl.h pulls in windows.h, which defines `max` as a macro
  // unless NOMINMAX was set first - and a header cannot set it for a consumer who has
  // already included windows.h. The ternary is immune.
  const int attempts = options.max_attempts < 1 ? 1 : options.max_attempts;

  for (int attempt = 1; ; ++attempt) {
    auto failure = fetch(url, options, body);

    if (!failure.has_value()) return std::nullopt;

    if (!failure->transient || attempt >= attempts) return failure;

    if (options.log) {
      options.log("tabbit: " + failure->message + " Retrying in "
                  + std::to_string(delay.count() / 1000.0).substr(0, 4) + "s ("
                  + std::to_string(attempt) + " of " + std::to_string(attempts) + ").");
    }

    std::this_thread::sleep_for(delay);

    // Doubling rather than a fixed wait: a server refusing because it is overloaded is
    // not helped by every client coming back at the same interval.
    delay *= 2;
  }
}

// ------------------------------------------------------------------------------ disk

inline std::filesystem::path local_path(const std::filesystem::path& directory,
                                        const std::string& name) {
  std::filesystem::path resolved = directory;

  std::size_t start = 0;

  for (;;) {
    const std::size_t slash = name.find('/', start);
    const std::string part = name.substr(start, slash - start);

    if (!part.empty()) resolved /= part;

    if (slash == std::string::npos) break;

    start = slash + 1;
  }

  return resolved;
}

inline bool write_file(const std::filesystem::path& path,
                       const std::vector<std::uint8_t>& data) {
  std::ofstream file(path, std::ios::binary | std::ios::trunc);

  if (!file) return false;

  if (!data.empty())
    file.write(reinterpret_cast<const char*>(data.data()),
               static_cast<std::streamsize>(data.size()));

  file.close();
  return static_cast<bool>(file);
}

/// Reads the cached manifest.
///
/// A missing or unreadable one is an empty manifest, which makes the next update fetch
/// everything - the safe direction to be wrong in.
inline std::vector<ManifestEntry> read_local_manifest(const std::filesystem::path& path) {
  std::ifstream file(path, std::ios::binary);

  if (!file) return {};

  const std::string text((std::istreambuf_iterator<char>(file)),
                         std::istreambuf_iterator<char>());

  return parse_manifest(text);
}

}  // namespace detail

/// The MD5 of some bytes, in the lower-case hex the manifest carries.
inline std::string md5_hex(const std::vector<std::uint8_t>& data) {
  return detail::md5_hex(data.data(), data.size());
}

/// Brings `cache_directory` up to date with the data served under `base_url`.
///
/// Does not throw. Everything that can go wrong here - the network, the disk, a file that
/// arrived corrupt - is a condition the caller has to handle rather than a defect, and a
/// patcher that throws into a program's startup is one that gets wrapped in a bare catch
/// that swallows the reason.
inline UpdateResult update(const std::string& base_url,
                           const std::filesystem::path& cache_directory,
                           const UpdateOptions& options = UpdateOptions()) {
  UpdateResult result;
  result.local_path = cache_directory;

  const auto log = [&options](const std::string& message) {
    if (options.log) options.log(message);
  };

  const auto fail = [&result, &log](const std::string& message) {
    result.succeeded = false;
    result.error = message;

    log("tabbit: update failed: " + message);
    return result;
  };

  try {
    std::vector<std::uint8_t> body;

    if (auto failure = detail::download(
            detail::join_url(base_url, options.manifest_file_name), options, &body))
      return fail(failure->message);

    const std::string manifest_text(body.begin(), body.end());
    const std::vector<ManifestEntry> remote = parse_manifest(manifest_text);

    if (remote.empty() && manifest_text.find("\"Items\"") == std::string::npos)
      return fail("the manifest could not be read: it has no Items array.");

    const std::vector<ManifestEntry> local =
        detail::read_local_manifest(cache_directory / options.manifest_file_name);

    std::map<std::string, const ManifestEntry*> by_name;
    for (const auto& entry : local) by_name[entry.name] = &entry;

    std::vector<const ManifestEntry*> wanted;

    for (const auto& entry : remote) {
      const auto found = by_name.find(entry.name);

      // The file's presence is checked as well as the manifest's word for it: a cache
      // somebody cleaned out by hand would otherwise never be refilled.
      const bool current =
          found != by_name.end() && found->second->hash == entry.hash
          && std::filesystem::exists(detail::local_path(cache_directory, entry.name));

      if (!current) wanted.push_back(&entry);
    }

    std::vector<std::string> gone;

    for (const auto& entry : local) {
      const bool served = std::any_of(remote.begin(), remote.end(),
                                      [&entry](const ManifestEntry& candidate) {
                                        return candidate.name == entry.name;
                                      });

      if (!served) gone.push_back(entry.name);
    }

    if (wanted.empty() && gone.empty()) {
      log("tabbit: already up to date.");

      result.succeeded = true;
      result.up_to_date = true;
      return result;
    }

    log("tabbit: " + std::to_string(wanted.size()) + " file(s) to fetch, "
        + std::to_string(gone.size()) + " to remove.");

    // Everything lands here first. Nothing the caller can read is touched until the last
    // file has arrived and been checked.
    const std::filesystem::path staging = cache_directory / ".staging";

    std::filesystem::create_directories(cache_directory);
    std::error_code ignored;
    std::filesystem::remove_all(staging, ignored);
    std::filesystem::create_directories(staging);

    for (const ManifestEntry* entry : wanted) {
      if (auto failure = detail::download(detail::join_url(base_url, entry->name),
                                          options, &body)) {
        std::filesystem::remove_all(staging, ignored);
        return fail(failure->message);
      }

      if (options.verify_hash && !entry->hash.empty()) {
        const std::string actual = detail::md5_hex(body.data(), body.size());

        std::string expected = entry->hash;
        std::transform(expected.begin(), expected.end(), expected.begin(),
                       [](unsigned char c) { return static_cast<char>(std::tolower(c)); });

        if (actual != expected) {
          std::filesystem::remove_all(staging, ignored);

          return fail("'" + entry->name + "' arrived with hash " + actual
                      + ", and the manifest says " + entry->hash
                      + ". Nothing was replaced.");
        }
      }

      const std::filesystem::path staged = detail::local_path(staging, entry->name);

      std::filesystem::create_directories(staged.parent_path());

      if (!detail::write_file(staged, body)) {
        std::filesystem::remove_all(staging, ignored);
        return fail("'" + entry->name + "' could not be staged.");
      }

      result.downloaded_bytes += static_cast<std::int64_t>(body.size());
    }

    // From here on the update is applied. Nothing below reaches the network.
    for (const std::string& name : gone) {
      std::filesystem::remove(detail::local_path(cache_directory, name), ignored);
      result.deleted_count += 1;
    }

    for (const ManifestEntry* entry : wanted) {
      const std::filesystem::path target = detail::local_path(cache_directory, entry->name);

      std::filesystem::create_directories(target.parent_path());
      std::filesystem::remove(target, ignored);
      std::filesystem::rename(detail::local_path(staging, entry->name), target);

      result.downloaded_count += 1;
    }

    // Last, and that ordering is the recovery story: a run killed before this point
    // leaves a manifest describing the data that is still on disk, so the next run
    // fetches the same files again rather than believing it has them.
    const std::vector<std::uint8_t> manifest_bytes(manifest_text.begin(),
                                                   manifest_text.end());

    if (!detail::write_file(cache_directory / options.manifest_file_name, manifest_bytes))
      return fail("the manifest could not be written to the cache.");

    std::filesystem::remove_all(staging, ignored);

    log("tabbit: updated. " + std::to_string(result.downloaded_count) + " fetched, "
        + std::to_string(result.deleted_count) + " removed.");

    result.succeeded = true;
    return result;
  } catch (const std::exception& error) {
    // The previous data is untouched, so the caller can carry on with it.
    return fail(error.what());
  }
}

}  // namespace tabbit

#endif  // TABBIT_UPDATER_H
